package dev.lain.claudejb.session

/**
 * Tells the user's own words apart from the binary's, inside a `user` line of a session transcript.
 *
 * **The bug this exists for.** Restoring a conversation showed, attributed to the user and styled as their
 * prompt, things they never typed: `<local-command-caveat>Caveat: The messages below were generated by the
 * user while running local commands. DO NOT respond to these…`, `<command-name>/compact</command-name>`,
 * `<task-notification>…`. They arrive as ordinary `text` blocks on a `user` line, so the reader — which
 * mapped every such block to a USER row — could not tell them apart. Reading your own transcript back and
 * finding paragraphs you never wrote is the kind of defect that makes the whole view untrustworthy.
 *
 * **The tag set is closed, and deliberately so.** Only the wrappers the binary is known to emit are treated
 * as synthetic (inventoried from real transcripts: `task-notification`, `local-command-caveat`,
 * `command-name`, `command-message`, `local-command-stdout`). A generic "anything starting with a tag is not
 * the user" rule would silently eat a prompt that legitimately starts with XML — and someone pasting markup
 * into a chat about markup is not an edge case here.
 *
 * Pure and side-effect free, so the rules are testable without a session, a file or an IDE.
 */
internal object SyntheticUserText {

    /** What a `user` line's text block turns out to be. */
    sealed interface Kind {
        /** The user's own words: rendered as their prompt, unchanged. */
        data class Prompt(val text: String) : Kind

        /** A slash command they ran (`/compact`): still theirs, shown the way they typed it. */
        data class Command(val text: String) : Kind

        /** The binary talking: rendered as a system note, the same as the live path does. */
        data class SystemNote(val text: String) : Kind

        /** Internal scaffolding with nothing to show — dropped. */
        data object Hidden : Kind
    }

    /**
     * Classifies one `text` block. [isMeta] is the line's own `isMeta` flag, which the binary sets on the
     * scaffolding it injects; it is honoured because it is the binary's own statement about the line, and it
     * catches wrappers this list has not met yet.
     */
    fun classify(text: String, isMeta: Boolean = false): Kind {
        val body = text.trim()
        if (body.isEmpty()) return Kind.Hidden
        val tag = leadingTag(body)
        return when {
            // A `/compact` the user ran: their action, so it stays theirs — shown as the command they typed
            // rather than as the three XML blocks the binary records it in.
            tag == COMMAND_NAME || tag == COMMAND_MESSAGE -> commandOf(body)?.let(Kind::Command) ?: Kind.Hidden

            // The binary's own voice. The live path renders these as system notices, so a restored
            // transcript renders them the same way instead of putting them in the user's mouth.
            tag == LOCAL_COMMAND_STDOUT -> inner(body, LOCAL_COMMAND_STDOUT)
                ?.let(Kind::SystemNote) ?: Kind.Hidden

            tag == TASK_NOTIFICATION -> taskNotice(body)?.let(Kind::SystemNote) ?: Kind.Hidden

            // An instruction aimed at the model, never at the reader.
            tag == LOCAL_COMMAND_CAVEAT -> Kind.Hidden

            // The binary flagged the line as its own scaffolding; believe it.
            isMeta -> Kind.Hidden

            else -> Kind.Prompt(body)
        }
    }

    /** `<command-name>/compact</command-name> … <command-args>x</command-args>` → `/compact x`. */
    private fun commandOf(body: String): String? {
        val name = inner(body, COMMAND_NAME) ?: inner(body, COMMAND_MESSAGE) ?: return null
        val args = inner(body, COMMAND_ARGS).orEmpty()
        val command = if (name.startsWith("/")) name else "/$name"
        return listOf(command, args).filter { it.isNotBlank() }.joinToString(" ")
    }

    /**
     * A settled subagent, condensed to its summary — the same shape the live path shows.
     *
     * The raw block carries ids, an output path and a note aimed at the model; none of that is a sentence a
     * human wants in their transcript, and the summary is the one line that says what happened.
     */
    private fun taskNotice(body: String): String? {
        val summary = inner(body, "summary")?.takeIf { it.isNotBlank() } ?: return null
        val status = inner(body, "status")?.takeIf { it.isNotBlank() }
        return if (status == null) summary else "Subagent $status: $summary"
    }

    /** The first `<tag>` of [body], or null when it does not start with one. */
    private fun leadingTag(body: String): String? =
        LEADING_TAG.find(body)?.groupValues?.get(1)

    /** The text inside `<tag>…</tag>`, trimmed; null when the tag is absent. */
    private fun inner(body: String, tag: String): String? =
        Regex("<$tag>(.*?)</$tag>", RegexOption.DOT_MATCHES_ALL).find(body)?.groupValues?.get(1)?.trim()

    private val LEADING_TAG = Regex("^<([a-z][a-z0-9-]*)>")

    private const val TASK_NOTIFICATION = "task-notification"
    private const val LOCAL_COMMAND_CAVEAT = "local-command-caveat"
    private const val LOCAL_COMMAND_STDOUT = "local-command-stdout"
    private const val COMMAND_NAME = "command-name"
    private const val COMMAND_MESSAGE = "command-message"
    private const val COMMAND_ARGS = "command-args"
}
